<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Link2, Plus, Save, Trash2 } from '@lucide/vue'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Checkbox } from '@/components/ui/checkbox'
import { Field, FieldGroup, FieldLabel } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { ApiError, errorMessageKey } from '@/lib/api'
import { footerApi, type NavigationGroupResult, type NavigationItem, type NavigationLocale } from '@/modules/footer-navigation/api'
import { useAuthStore } from '@/stores/auth'
import { useI18n } from 'vue-i18n'

const { t } = useI18n()
const auth = useAuthStore()
const groups = ref<NavigationGroupResult[]>([])
const loading = ref(true)
const saving = ref(false)
const error = ref('')
const groupForm = reactive({ id: 0, title_zh_cn: '', title_en_us: '', locale: 'all' as NavigationLocale, sort_order: 0, is_enabled: true })
const itemForm = reactive({ id: 0, group_id: 0, parent_id: null as number | null, label_zh_cn: '', label_en_us: '', target_type: 'page' as NavigationItem['target_type'], target_value: '', open_in_new_tab: false, sort_order: 0, is_enabled: true })
const navigationLocales: NavigationLocale[] = ['all', 'zh-CN', 'en-US']
const canManage = computed(() => auth.can('admin.footer_navigation.manage'))

function localError(value: unknown) { return value instanceof ApiError ? t(errorMessageKey(value.code)) : t('footerNavigation.saveFailed') }
function localeLabel(value: NavigationLocale) { return t(`footerNavigation.locales.${value}`) }
function targetLabel(value: NavigationItem['target_type']) { return t(`footerNavigation.targetTypes.${value}`) }
async function load() { if (!auth.token) return; loading.value = true; error.value = ''; try { groups.value = await footerApi.list(auth.token) } catch (value) { error.value = localError(value) } finally { loading.value = false } }
function editGroup(value: NavigationGroupResult['group']) { groupForm.id = Number(value.id); groupForm.title_zh_cn = value.title_zh_cn || value.title || ''; groupForm.title_en_us = value.title_en_us || ''; groupForm.locale = value.locale || 'all'; groupForm.sort_order = Number(value.sort_order || 0); groupForm.is_enabled = Boolean(value.is_enabled) }
function editItem(value: NavigationItem) { itemForm.id = Number(value.id); itemForm.group_id = Number(value.group_id); itemForm.parent_id = value.parent_id == null ? null : Number(value.parent_id); itemForm.label_zh_cn = value.label_zh_cn || value.label || ''; itemForm.label_en_us = value.label_en_us || ''; itemForm.target_type = value.target_type; itemForm.target_value = value.target_value; itemForm.open_in_new_tab = Boolean(value.open_in_new_tab); itemForm.sort_order = Number(value.sort_order || 0); itemForm.is_enabled = Boolean(value.is_enabled) }
function resetGroup() { Object.assign(groupForm, { id: 0, title_zh_cn: '', title_en_us: '', locale: 'all', sort_order: 0, is_enabled: true }) }
function resetItem(groupID = 0) { Object.assign(itemForm, { id: 0, group_id: groupID, parent_id: null, label_zh_cn: '', label_en_us: '', target_type: 'page', target_value: '', open_in_new_tab: false, sort_order: 0, is_enabled: true }) }
async function saveGroup() { if (!auth.token || !canManage.value) return; saving.value = true; error.value = ''; try { const input = { title_zh_cn: groupForm.title_zh_cn, title_en_us: groupForm.title_en_us, locale: groupForm.locale, sort_order: groupForm.sort_order, is_enabled: groupForm.is_enabled }; groupForm.id ? await footerApi.updateGroup(groupForm.id, input, auth.token) : await footerApi.createGroup(input, auth.token); resetGroup(); await load() } catch (value) { error.value = localError(value) } finally { saving.value = false } }
async function saveItem() { if (!auth.token || !canManage.value) return; saving.value = true; error.value = ''; try { const input = { group_id: itemForm.group_id, parent_id: itemForm.parent_id || null, label_zh_cn: itemForm.label_zh_cn, label_en_us: itemForm.label_en_us, target_type: itemForm.target_type, target_value: itemForm.target_value, open_in_new_tab: itemForm.open_in_new_tab, sort_order: itemForm.sort_order, is_enabled: itemForm.is_enabled }; itemForm.id ? await footerApi.updateItem(itemForm.id, input, auth.token) : await footerApi.createItem(input, auth.token); resetItem(itemForm.group_id); await load() } catch (value) { error.value = localError(value) } finally { saving.value = false } }
async function removeGroup(id: number) { if (!auth.token || !canManage.value || !window.confirm(t('footerNavigation.confirmDeleteGroup'))) return; await footerApi.deleteGroup(id, auth.token); await load() }
async function removeItem(id: number) { if (!auth.token || !canManage.value || !window.confirm(t('footerNavigation.confirmDeleteItem'))) return; await footerApi.deleteItem(id, auth.token); await load() }
onMounted(load)
</script>

<template>
  <div class="flex flex-col gap-6">
    <div class="flex items-center gap-3"><Link2 class="size-5 text-primary" /><div><h1 class="text-2xl font-semibold tracking-tight">{{ t('footerNavigation.title') }}</h1><p class="mt-1 text-sm text-muted-foreground">{{ t('footerNavigation.description') }}</p></div></div>
    <Alert v-if="error" variant="destructive"><AlertTitle>{{ t('states.errorTitle') }}</AlertTitle><AlertDescription>{{ error }}</AlertDescription></Alert>
    <Card><CardHeader><CardTitle>{{ t('footerNavigation.groupForm') }}</CardTitle><CardDescription>{{ t('footerNavigation.groupFormDescription') }}</CardDescription></CardHeader><CardContent><form class="grid gap-4 md:grid-cols-4" @submit.prevent="saveGroup"><Field><FieldLabel for="footer-group-title-zh">{{ t('footerNavigation.groupTitleZh') }}</FieldLabel><Input id="footer-group-title-zh" v-model="groupForm.title_zh_cn" required /></Field><Field><FieldLabel for="footer-group-title-en">{{ t('footerNavigation.groupTitleEn') }}</FieldLabel><Input id="footer-group-title-en" v-model="groupForm.title_en_us" required /></Field><Field><FieldLabel for="footer-group-locale">{{ t('footerNavigation.locale') }}</FieldLabel><select id="footer-group-locale" v-model="groupForm.locale" class="h-9 w-full rounded-lg border bg-background px-2 text-sm"><option v-for="value in navigationLocales" :key="value" :value="value">{{ localeLabel(value) }}</option></select></Field><Field><FieldLabel for="footer-group-order">{{ t('footerNavigation.sortOrder') }}</FieldLabel><Input id="footer-group-order" v-model.number="groupForm.sort_order" type="number" /></Field><div class="flex items-end gap-2 md:col-span-4"><label class="flex min-h-9 items-center gap-2 text-sm"><Checkbox :model-value="groupForm.is_enabled" @update:model-value="groupForm.is_enabled = Boolean($event)" />{{ t('footerNavigation.enabled') }}</label><Button type="submit" :disabled="saving || !canManage"><Save data-icon="inline-start" />{{ groupForm.id ? t('resource.save') : t('footerNavigation.addGroup') }}</Button><Button v-if="groupForm.id" type="button" variant="ghost" @click="resetGroup">{{ t('resource.cancel') }}</Button></div></form></CardContent></Card>
    <Card><CardHeader><CardTitle>{{ t('footerNavigation.itemForm') }}</CardTitle><CardDescription>{{ t('footerNavigation.itemFormDescription') }}</CardDescription></CardHeader><CardContent><form class="grid gap-4 md:grid-cols-4" @submit.prevent="saveItem"><Field><FieldLabel for="footer-item-group">{{ t('footerNavigation.group') }}</FieldLabel><select id="footer-item-group" v-model.number="itemForm.group_id" class="h-9 w-full rounded-lg border bg-background px-2 text-sm" required><option :value="0" disabled>{{ t('footerNavigation.chooseGroup') }}</option><option v-for="entry in groups" :key="entry.group.id" :value="entry.group.id">{{ entry.group.title_zh_cn || entry.group.title }}</option></select></Field><Field><FieldLabel for="footer-item-parent">{{ t('footerNavigation.parent') }}</FieldLabel><select id="footer-item-parent" v-model="itemForm.parent_id" class="h-9 w-full rounded-lg border bg-background px-2 text-sm"><option :value="null">{{ t('footerNavigation.topLevel') }}</option><option v-for="item in groups.find((entry) => entry.group.id === itemForm.group_id)?.items || []" :key="item.id" :value="item.id">{{ item.label_zh_cn || item.label }}</option></select></Field><Field><FieldLabel for="footer-item-label-zh">{{ t('footerNavigation.itemLabelZh') }}</FieldLabel><Input id="footer-item-label-zh" v-model="itemForm.label_zh_cn" required /></Field><Field><FieldLabel for="footer-item-label-en">{{ t('footerNavigation.itemLabelEn') }}</FieldLabel><Input id="footer-item-label-en" v-model="itemForm.label_en_us" required /></Field><Field><FieldLabel for="footer-item-type">{{ t('footerNavigation.targetType') }}</FieldLabel><select id="footer-item-type" v-model="itemForm.target_type" class="h-9 w-full rounded-lg border bg-background px-2 text-sm"><option value="page">{{ t('footerNavigation.targetPage') }}</option><option value="route">{{ t('footerNavigation.targetRoute') }}</option><option value="external">{{ t('footerNavigation.targetExternal') }}</option><option value="friends">{{ t('footerNavigation.targetFriends') }}</option></select></Field><Field class="md:col-span-2"><FieldLabel for="footer-item-value">{{ t('footerNavigation.targetValue') }}</FieldLabel><Input id="footer-item-value" v-model="itemForm.target_value" required /><p class="text-xs text-muted-foreground">{{ t('footerNavigation.targetHint') }}</p></Field><Field><FieldLabel for="footer-item-order">{{ t('footerNavigation.sortOrder') }}</FieldLabel><Input id="footer-item-order" v-model.number="itemForm.sort_order" type="number" /></Field><div class="flex items-end gap-2 md:col-span-4"><label class="flex min-h-9 items-center gap-2 text-sm"><Checkbox :model-value="itemForm.is_enabled" @update:model-value="itemForm.is_enabled = Boolean($event)" />{{ t('footerNavigation.enabled') }}</label><Button type="submit" :disabled="saving || !canManage"><Plus data-icon="inline-start" />{{ itemForm.id ? t('resource.save') : t('footerNavigation.addItem') }}</Button><Button v-if="itemForm.id" type="button" variant="ghost" @click="resetItem(itemForm.group_id)">{{ t('resource.cancel') }}</Button></div></form></CardContent></Card>
    <div v-if="loading" class="text-sm text-muted-foreground">{{ t('resource.loading') }}</div>
    <div v-else class="grid gap-4"> <Card v-for="entry in groups" :key="entry.group.id"><CardHeader class="flex flex-row items-center justify-between"><div><CardTitle>{{ entry.group.title_zh_cn || entry.group.title }}</CardTitle><CardDescription><span>{{ t('footerNavigation.chineseLabel') }}{{ t('footerNavigation.valueSeparator') }}{{ entry.group.title_zh_cn || t('footerNavigation.missingTranslation') }}</span><span class="ml-3">{{ t('footerNavigation.englishLabel') }}{{ t('footerNavigation.valueSeparator') }}{{ entry.group.title_en_us || t('footerNavigation.missingTranslation') }}</span><span class="ml-3">{{ localeLabel(entry.group.locale) }} {{ t('footerNavigation.statusSeparator') }} {{ entry.group.is_enabled ? t('footerNavigation.enabled') : t('footerNavigation.disabled') }}</span></CardDescription></div><div class="flex gap-2"><Button v-if="canManage" type="button" variant="outline" size="sm" @click.stop="editGroup(entry.group)">{{ t('content.edit') }}</Button><Button v-if="canManage" type="button" variant="ghost" size="icon" @click.stop="removeGroup(entry.group.id)"><Trash2 class="size-4" /></Button></div></CardHeader><CardContent><div v-if="!entry.items.length" class="text-sm text-muted-foreground">{{ t('footerNavigation.noItems') }}</div><div v-else class="divide-y rounded-md border"><div v-for="item in entry.items" :key="item.id" class="flex items-center justify-between gap-3 p-3"><div class="min-w-0"><p class="font-medium"><span v-if="item.parent_id" class="mr-2 text-xs text-muted-foreground">{{ t('footerNavigation.submenu') }}</span>{{ item.label_zh_cn || item.label }}</p><p class="text-xs text-muted-foreground">{{ t('footerNavigation.chineseLabel') }}{{ t('footerNavigation.valueSeparator') }}{{ item.label_zh_cn || t('footerNavigation.missingTranslation') }} <span class="ml-3">{{ t('footerNavigation.englishLabel') }}{{ t('footerNavigation.valueSeparator') }}{{ item.label_en_us || t('footerNavigation.missingTranslation') }}</span></p><p class="truncate text-xs text-muted-foreground">{{ targetLabel(item.target_type) }}{{ t('footerNavigation.valueSeparator') }}{{ item.target_value }}</p></div><div class="flex gap-2"><Button v-if="canManage" type="button" variant="ghost" size="sm" @click.stop="editItem(item)">{{ t('content.edit') }}</Button><Button v-if="canManage" type="button" variant="ghost" size="icon" @click.stop="removeItem(item.id)"><Trash2 class="size-4" /></Button></div></div></div></CardContent></Card></div>
  </div>
</template>
